#include <array>
#include <iostream>
#include <numeric>

int main() {
    constexpr std::array<double, 4> measurements{1.2, 1.4, 1.1, 1.3};
    const double total = std::accumulate(measurements.begin(), measurements.end(), 0.0);
    std::cout << "mean=" << total / measurements.size() << '\n';
}
